<section class="auth-section auth-centered container"><form method="post" class="form-card auth-card" action="<?= e(url('verify')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="phone-check"><span class="step-icon"><?= icon('phone') ?></span><h1><?= t('أكد رقمك','Verify your number') ?></h1><p><?= t('اكتب رمز الـ SMS المرسل إلى','Enter the SMS code sent to') ?> <b dir="ltr"><?= e($c['phone']??'') ?></b></p><?php field(t('رمز التأكيد — ٦ أرقام','Verification code — six digits'),'code','text','','required pattern="[0-9٠-٩]{6}" maxlength="6" inputmode="numeric" autocomplete="one-time-code" class="otp-input" dir="ltr" autofocus'); ?><?php if(local_otp_allowed() && isset($_SESSION['local_code'])): ?><p class="note"><?= t('اختبار محلي فقط. الرمز: ','Local test only. Code: ') ?><b><?= e($_SESSION['local_code']) ?></b></p><?php endif; ?><button type="submit" class="button button-green button-full"><?= t('تأكيد ودخول','Verify & sign in') ?></button><a class="text-link" href="<?= e(url('login')) ?>"><?= t('تغيير الرقم / طلب رمز جديد','Change number / request a new code') ?></a><p class="caption"><?= t('الرمز صالح لمدة ١٠ دقائق وبحد أقصى ٥ محاولات.','Codes expire after 10 minutes and allow up to 5 attempts.') ?></p></form></section>
